# Generates src/common_strings.h from UnityPy's built-in typetree string table.
import os
from UnityPy.helpers.Tpk import get_common_strings

items = sorted(get_common_strings().items())
buf = b''
for off, s in items:
    assert len(buf) == off, (off, len(buf))
    buf += s.encode() + b'\0'

out = ['// Unity built-in typetree string table (offsets with the 0x80000000 bit).',
       '// Generated by tools/gen_common_strings.py from UnityPy.',
       '#pragma once',
       'static const unsigned char kCommonStrings[] = {']
for i in range(0, len(buf), 24):
    out.append('    ' + ', '.join(str(b) for b in buf[i:i + 24]) + ',')
out.append('};')
out.append(f'static const unsigned kCommonStringsSize = {len(buf)};')

here = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(here, '..', 'src', 'common_strings.h'), 'w') as f:
    f.write('\n'.join(out) + '\n')
print(len(items), 'strings,', len(buf), 'bytes')
